import random
import sys


def simulates_dice_rolls():
    """simulates 100 dice rolls"""
    rolls = []
    for _ in range(100):
        roll = random.randint(1, 6)
        rolls.append(roll)
    return rolls

def counts_face(previous):
    """counts each face"""
    face_counts = {}
    for face in previous:
        if face in face_counts:
            face_counts[face] += 1
        else:
            face_counts[face] = 1
    histogram = {face: count for face, count in face_counts.items()}
    print(histogram)

